*** Update File: /app/src/cli/transformers.ts
@@
-import execa from 'execa'
+import { spawnSync } from 'child_process'
 import path from 'path'
@@
 type Files = string | string[]
+
+type SyncResult = {
+  error?: Error
+  signal?: NodeJS.Signals | null
+  status?: number | null
+  stderr?: Buffer | Error | string | null
+}
+
+type SyncExecutor = (
+  file: string,
+  args: string[],
+  options: { stdio: 'inherit'; stripFinalNewline?: boolean }
+) => SyncResult
@@
 export type Parser = 'babel' | 'flow' | 'ts' | 'tsx'
+
+function getSyncExecutor(): SyncExecutor {
+  try {
+    // execa@6 is ESM-only. This keeps Jest's CommonJS mock usable, while real
+    // runtime execution falls back to child_process below.
+    // eslint-disable-next-line @typescript-eslint/no-var-requires
+    const execa = require('execa') as { sync?: SyncExecutor }
+
+    if (execa.sync) {
+      return execa.sync
+    }
+  } catch (error) {
+    if ((error as { code?: string }).code !== 'ERR_REQUIRE_ESM') {
+      throw error
+    }
+  }
+
+  return (file, args, options) => spawnSync(file, args, { stdio: options.stdio })
+}
@@
-  const result = execa.sync('node', [jscodeshiftExecutable, ...args], {
+  const result = getSyncExecutor()('node', [jscodeshiftExecutable, ...args], {
     stdio: 'inherit',
     stripFinalNewline: false,
   })

+  if (result.error) {
+    throw result.error
+  }
+
   if (result.stderr) {
     throw result.stderr
   }
+
+  if (result.signal) {
+    throw new Error(`jscodeshift exited with signal ${result.signal}`)
+  }
+
+  if (result.status) {
+    throw new Error(`jscodeshift exited with status ${result.status}`)
+  }
 }
